func (q *Queries) SessionTenant(ctx context.Context, db DBTX, arg SessionTenantParams) ([]SessionTenantRow, error) {
	rows, err := db.Query(ctx, sessionTenant, arg.Domain, arg.Surface, arg.TokenHash)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SessionTenantRow
	for rows.Next() {
		var i SessionTenantRow
		if err := rows.Scan(&i.SessionID, &i.UserID, &i.AccountID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setSessionRecoveryCodes = `-- name: SetSessionRecoveryCodes :exec
UPDATE accounts.sessions
SET recovery_codes_ciphertext = $1, recovery_codes_nonce = $2
WHERE id = $3
`

type SetSessionRecoveryCodesParams struct {
	Ciphertext []byte
	Nonce      []byte
	ID         uuid.UUID
}

// Codes for the console to read once, encrypted under the session token, when the answer that made them is a redirect
// (a provider link).
func (q *Queries) SetSessionRecoveryCodes(ctx context.Context, db DBTX, arg SetSessionRecoveryCodesParams) error {
	_, err := db.Exec(ctx, setSessionRecoveryCodes, arg.Ciphertext, arg.Nonce, arg.ID)
	return err
}

const touchSession = `-- name: TouchSession :exec
UPDATE accounts.sessions SET last_seen_at = now() WHERE id = $1 AND last_seen_at < now() - interval '1 minute'
`

// Idle time counts from the last request, written at most once a minute.
func (q *Queries) TouchSession(ctx context.Context, db DBTX, id uuid.UUID) error {
	_, err := db.Exec(ctx, touchSession, id)
	return err
}

const useRecoveryCode = `-- name: UseRecoveryCode :execrows
UPDATE accounts.recovery_codes SET used_at = now()
WHERE user_id = $1 AND code_hash = $2 AND factor_version = $3
`

type UseRecoveryCodeParams struct {
	UserID        uuid.UUID
	CodeHash      []byte
	FactorVersion int64
}

// A code of the current factor version not used yet; the table's policy updates only unused codes.
func (q *Queries) UseRecoveryCode(ctx context.Context, db DBTX, arg UseRecoveryCodeParams) (int64, error) {
	result, err := db.Exec(ctx, useRecoveryCode, arg.UserID, arg.CodeHash, arg.FactorVersion)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const userPassword = `-- name: UserPassword :many
SELECT password_hash, factor_version FROM accounts.users WHERE id = $1
`

type UserPasswordRow struct {
	PasswordHash  string
	FactorVersion int64
}

// Read before the issuing transaction, so the slow hash runs outside it.
func (q *Queries) UserPassword(ctx context.Context, db DBTX, id uuid.UUID) ([]UserPasswordRow, error) {
	rows, err := db.Query(ctx, userPassword, id)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UserPasswordRow
	for rows.Next() {
		var i UserPasswordRow
		if err := rows.Scan(&i.PasswordHash, &i.FactorVersion); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const validSession = `-- name: ValidSession :many
SELECT s.site_id, s.surface, s.level, s.csrf_token, s.factor_version,
    EXISTS (
        SELECT 1
        FROM accounts.legal_documents d
        WHERE d.site_id = s.site_id
            AND d.version = (SELECT max(x.version) FROM accounts.legal_documents x
                WHERE x.site_id = d.site_id AND x.kind = d.kind)
            AND NOT EXISTS (
                SELECT 1 FROM accounts.legal_acceptances a
                WHERE a.site_id = s.site_id AND a.user_id = s.user_id
                    AND a.kind = d.kind AND a.version >= d.version
            )
    ) AS consent_pending
FROM accounts.sessions s
JOIN accounts.users u ON u.site_id = s.site_id AND u.account_id = s.account_id AND u.id = s.user_id
WHERE s.id = $1 AND s.revoked_at IS NULL AND s.expires_at > now()
    AND s.created_at + make_interval(secs => $2::bigint) > now()
    AND s.last_seen_at + least(s.idle_timeout, make_interval(secs => $3::bigint)) > now()
    AND u.status = 'active' AND u.factor_version = s.factor_version
`

type ValidSessionParams struct {
	ID            uuid.UUID
	MaxAgeSeconds int64
	IdleSeconds   int64
}

type ValidSessionRow struct {
	SiteID         uuid.UUID
	Surface        string
	Level          string
	CsrfToken      string
	FactorVersion  int64
	ConsentPending bool
}

// A session holds while it is not revoked, expired or idle too long, its user is enabled, and its factor version is
// the user's. The site's lifetimes now (the caller's, in seconds) cut what the session was issued with, never extend it:
// a site that shortens its sessions writes that into the ones already made (CutSessions), and this cut also holds a
// session another node issued from its snapshot before reloading the change.
func (q *Queries) ValidSession(ctx context.Context, db DBTX, arg ValidSessionParams) ([]ValidSessionRow, error) {
	rows, err := db.Query(ctx, validSession, arg.ID, arg.MaxAgeSeconds, arg.IdleSeconds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ValidSessionRow
	for rows.Next() {
		var i ValidSessionRow
		if err := rows.Scan(
			&i.SiteID,
			&i.Surface,
			&i.Level,
			&i.CsrfToken,
			&i.FactorVersion,
			&i.ConsentPending,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
